t "queue fixtures" ok "INSERT INTO Business (BusinessID,Name) VALUES ('B1','Queue'); INSERT INTO Location (LocationID,BusinessID,Name,TimeZone) VALUES ('L1','B1','Main','America/Chicago'),('L2','B1','Other','America/Chicago'); INSERT INTO StockItem (StockItemID,BusinessID,Name,StockUnitCode) VALUES ('S1','B1','Cups',1),('S2','B1','Off',1); UPDATE StockItem SET Active=0 WHERE StockItemID='S2'; INSERT INTO Inventory (InventoryID,LocationID,StockItemID,BusinessID) VALUES ('I1','L1','S1','B1'),('I2','L2','S1','B1'),('I3','L1','S2','B1');"
t "supplier fixtures" ok "INSERT INTO Supplier (SupplierID,BusinessID,Name) VALUES ('SU1','B1','Preferred'),('SU2','B1','Backup'); INSERT INTO StockItemSupplier (StockItemID,SupplierID,BusinessID,IsPreferred,UnitCost,MinOrderQty) VALUES ('S1','SU1','B1',1,1.25,5),('S1','SU2','B1',0,2.00,1);"
a "zero threshold disables queue" "SELECT COUNT(*) FROM PurchaseOrder" "0"
t "restock above threshold" ok "INSERT INTO InventoryTransaction (InventoryTransactionID,BusinessID,StockItemID,LocationID,QuantityChange,UnitCost,TransactionTypeCode) VALUES ('T1','B1','S1','L1',10,1,1); UPDATE Inventory SET ReorderThreshold=5 WHERE InventoryID='I1';"
a "healthy stock has no request" "SELECT COUNT(*) FROM PurchaseOrder" "0"
t "stock reaches threshold" ok "INSERT INTO InventoryTransaction (InventoryTransactionID,BusinessID,StockItemID,LocationID,QuantityChange,UnitCost,TransactionTypeCode) VALUES ('T2','B1','S1','L1',-5,1,8);"
a "inclusive threshold queues replenishment" "SELECT Quantity FROM PurchaseOrder WHERE InventoryID='I1'" "5.000"
a "supplier order created automatically" "SELECT CONCAT(Status,' / ',SupplierID,' / ',UnitCost) FROM PurchaseOrder WHERE InventoryID='I1'" "Ordered / SU1 / 1.250000"
a "order number assigned" "SELECT COUNT(*) FROM PurchaseOrder WHERE OrderNumber > 0" "1"
t "change current supplier quote" ok "UPDATE StockItemSupplier SET UnitCost=9, MinOrderQty=50 WHERE StockItemID='S1' AND SupplierID='SU1';"
a "placed order preserves price and quantity" "SELECT CONCAT(Quantity,' / ',UnitCost) FROM PurchaseOrder WHERE InventoryID='I1'" "5.000 / 1.250000"
t "further changes deduplicate" ok "UPDATE Inventory SET ReorderThreshold=6 WHERE InventoryID='I1'; INSERT INTO InventoryTransaction (InventoryTransactionID,BusinessID,StockItemID,LocationID,QuantityChange,UnitCost,TransactionTypeCode) VALUES ('T3','B1','S1','L1',-1,1,8);"
a "one open request with original quantity" "SELECT CONCAT(COUNT(*),' / ',MAX(Quantity)) FROM PurchaseOrder WHERE InventoryID='I1' AND ReceivedDeliveryID IS NULL" "1 / 5.000"
t "separate location queues separately" ok "UPDATE Inventory SET ReorderThreshold=2 WHERE InventoryID='I2';"
a "two locations" "SELECT COUNT(*) FROM PurchaseOrder" "2"
t "inactive items ignored" ok "UPDATE Inventory SET ReorderThreshold=2 WHERE InventoryID='I3';"
a "inactive item has no request" "SELECT COUNT(*) FROM PurchaseOrder WHERE InventoryID='I3'" "0"
t "rollback stock and queue together" ok "UPDATE StockItem SET Active=1 WHERE StockItemID='S2'; START TRANSACTION; UPDATE Inventory SET ReorderThreshold=3 WHERE InventoryID='I3'; ROLLBACK;"
a "rolled back threshold" "SELECT ReorderThreshold FROM Inventory WHERE InventoryID='I3'" "2.000"
a "rolled back queue entry" "SELECT COUNT(*) FROM PurchaseOrder WHERE InventoryID='I3'" "0"
t "new low-stock inventory queues immediately" ok "INSERT INTO Inventory (InventoryID,LocationID,StockItemID,BusinessID,ReorderThreshold) VALUES ('I4','L2','S2','B1',3);"
a "new request quantity" "SELECT Quantity FROM PurchaseOrder WHERE InventoryID='I4'" "6.000"
a "supplier minimum applied to next order" "SELECT Quantity FROM PurchaseOrder WHERE InventoryID='I2'" "50.000"
a "missing supplier is explicit" "SELECT Status FROM PurchaseOrder WHERE InventoryID='I4'" "Needs supplier"
